'use client';

import { useEffect, useMemo, useState } from 'react';

import {
  useAutoplay,
  type AutoplayStep,
} from '@/registry/ndeko/hooks/use-autoplay';
import { useKeptHeight } from '@/registry/ndeko/hooks/use-kept-height';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { CheckIcon, ScanIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';
import { Badge } from '@/registry/ndeko/ui/badge';
import { Swap } from '@/registry/ndeko/ui/chat-motion';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';
import { Segments, type Segment } from '@/registry/ndeko/ui/segments';

import { ScanCells } from './_parts/scan-cells';
import { BADGE_GAP, CARD_PADDING, GRID, grainsOf } from './_parts/scan-pattern';
import { useHover } from './_parts/use-hover';

type UnitStyle = React.CSSProperties & { '--u': string };

/** One module of the code: 9px, and narrower where the container is too narrow for the whole code. */
const UNIT_STYLE: UnitStyle = { '--u': 'min(0.5625rem, 3.4cqw)' };

const CARD_STYLE: React.CSSProperties = {
  padding: `calc(var(--u) * ${CARD_PADDING})`,
};

const CODE_STYLE: React.CSSProperties = {
  width: `calc(var(--u) * ${GRID})`,
};

const BADGE_STYLE: React.CSSProperties = {
  marginTop: `calc(var(--u) * ${BADGE_GAP})`,
};

/** The badge reads Scanned once most of the grains have landed in it. */
const LABEL_AT_MS = 1100;

/** The tint rises in the badge from the first grain that lands to the last. */
const FILL_DELAY_MS = 400;

const FILL_MS = 900;

const DRAIN_MS = 200;

const EASE_IN_OUT = 'cubic-bezier(0.77, 0, 0.175, 1)';

const EASE_OUT = 'cubic-bezier(0.23, 1, 0.32, 1)';

const STILL_FADE = 'opacity 200ms linear';

const STATUS_ROW = 'flex items-center gap-1.5';

const READY_LABEL = 'Ready to scan';

const SCANNED_LABEL = 'Scanned';

function landingDelayOf(isStill: boolean) {
  if (isStill) {
    return 0;
  }
  return LABEL_AT_MS;
}

function statusKeyOf(isScanned: boolean) {
  if (isScanned) {
    return 'scanned';
  }
  return 'ready';
}

function fillOpacityOf(isFilled: boolean) {
  if (isFilled) {
    return 1;
  }
  return 0;
}

function fillStyleOf(isFilled: boolean, isStill: boolean): React.CSSProperties {
  if (isStill) {
    return { opacity: fillOpacityOf(isFilled), transition: STILL_FADE };
  }
  if (isFilled) {
    const rise = `scale ${FILL_MS}ms ${EASE_IN_OUT} ${FILL_DELAY_MS}ms`;
    return { scale: '1 1', transition: rise };
  }
  return { scale: '1 0', transition: `scale ${DRAIN_MS}ms ${EASE_OUT}` };
}

/** True once the grains of a scan have had the time to land. Going back to unscanned is at once. */
function useLanded(isScanned: boolean, landingMs: number) {
  const [hasLanded, setHasLanded] = useState(isScanned);

  useEffect(() => {
    if (!isScanned || hasLanded) {
      return;
    }
    const timer = window.setTimeout(() => setHasLanded(true), landingMs);
    return () => window.clearTimeout(timer);
  }, [isScanned, hasLanded, landingMs]);

  if (!isScanned && hasLanded) {
    setHasLanded(false);
  }

  return isScanned && hasLanded;
}

type StatusProps = {
  isScanned: boolean;
  readyLabel: string;
  scannedLabel: string;
};

function Status({ isScanned, readyLabel, scannedLabel }: StatusProps) {
  if (isScanned) {
    return (
      <span className={STATUS_ROW}>
        <CheckIcon strokeWidth={2.25} />
        {scannedLabel}
      </span>
    );
  }
  return (
    <span className={STATUS_ROW}>
      <ScanIcon />
      {readyLabel}
    </span>
  );
}

export type ScanBadgeProps = {
  /** What the code stands for. Its cells are drawn from this text, so one text always draws one code. It is a picture of a code, not one a camera can read. */
  value: string;
  /** True once the code was scanned: its cells pour into the badge. Back to false, they grow back. */
  isScanned: boolean;
  /** What the badge says before the scan. */
  readyLabel?: string;
  /** What it says once the cells have landed. */
  scannedLabel?: string;
  className?: string;
};

/**
 * A code drawn in cells, with a badge under it. When the code is scanned the cells fall like grains
 * into the badge, which fills with the success tint as they land and then says Scanned; when it is
 * ready again they grow back from the top left corner. Each cell is a transition of its own, so the
 * browser moves them and nothing runs at rest. Under reduced motion the cells fade where they stand.
 * The change is not announced: say it where the scan is handled.
 */
export function ScanBadge({
  value,
  isScanned,
  readyLabel = READY_LABEL,
  scannedLabel = SCANNED_LABEL,
  className,
}: ScanBadgeProps) {
  const isStill = usePrefersReducedMotion();
  const grains = useMemo(() => grainsOf(value), [value]);
  const isLabelScanned = useLanded(isScanned, landingDelayOf(isStill));

  return (
    <div className={cn('@container w-full', className)}>
      <div
        style={UNIT_STYLE}
        className='mx-auto flex w-fit flex-col items-center'
      >
        <div
          style={CARD_STYLE}
          className='bg-card hairline-ring ring-border rounded-xl shadow-[0_1px_2px_rgb(0_0_0/0.04)]'
        >
          <div style={CODE_STYLE} className='relative aspect-square'>
            <ScanCells grains={grains} isFallen={isScanned} isStill={isStill} />
          </div>
        </div>
        <Badge
          variant='outline'
          data-scanned={isLabelScanned}
          style={BADGE_STYLE}
          className='data-[scanned=true]:text-success-foreground data-[scanned=true]:ring-success/30 relative z-10 h-6 gap-0 overflow-hidden rounded-full px-2.5 transition-[color,box-shadow] duration-300'
        >
          <span
            aria-hidden='true'
            style={fillStyleOf(isScanned, isStill)}
            className='bg-success/10 absolute inset-0 origin-bottom'
          />
          <AnimatedSize as='span' axis='width' contentClassName='relative flex'>
            <Swap swapKey={statusKeyOf(isLabelScanned)}>
              <Status
                isScanned={isLabelScanned}
                readyLabel={readyLabel}
                scannedLabel={scannedLabel}
              />
            </Swap>
          </AnimatedSize>
        </Badge>
      </div>
    </div>
  );
}

type ScanPhase = 'ready' | 'scanned';

const PHASES: Segment<ScanPhase>[] = [
  { value: 'ready', label: 'Ready' },
  { value: 'scanned', label: 'Scanned' },
];

/** Long enough in each state for the pour, the landing and the growing back to be seen whole. */
const READY_HOLD_MS = 1500;

const SCANNED_HOLD_MS = 3700;

const REGROW_HOLD_MS = 1200;

const SAMPLE_CODE = 'ndekoui-entry-0042';

function phaseOf(isScanned: boolean): ScanPhase {
  if (isScanned) {
    return 'scanned';
  }
  return 'ready';
}

function statusLineOf(isScanned: boolean) {
  if (isScanned) {
    return SCANNED_LABEL;
  }
  return READY_LABEL;
}

export default function Badge14() {
  const [isScanned, setIsScanned] = useState(false);
  const [announcement, setAnnouncement] = useState('');
  const { isHovered, hoverHandlers } = useHover();
  const steps: AutoplayStep[] = [
    { after: READY_HOLD_MS, run: () => setIsScanned(true) },
    { after: SCANNED_HOLD_MS, run: () => setIsScanned(false) },
  ];
  const { ref } = useAutoplay(steps, {
    loopAfter: REGROW_HOLD_MS,
    onReset: () => setIsScanned(false),
    isEnabled: !isHovered,
  });

  useKeptHeight(ref);

  function choose(phase: ScanPhase) {
    const isScannedNow = phase === 'scanned';
    setIsScanned(isScannedNow);
    setAnnouncement(statusLineOf(isScannedNow));
  }

  return (
    <div
      ref={ref}
      className='flex w-full max-w-[22rem] flex-col items-center gap-5'
      {...hoverHandlers}
    >
      <ScanBadge value={SAMPLE_CODE} isScanned={isScanned} />
      <Segments
        value={phaseOf(isScanned)}
        segments={PHASES}
        onValueChange={choose}
        label='Scan state'
      />
      <LiveRegion message={announcement} />
    </div>
  );
}

import { GRID, type Grain } from './scan-pattern';

type CellsStyle = React.CSSProperties & {
  '--cell': string;
  '--fall-ease': string;
};

/** A module is drawn a little smaller than its square, so the cells read as separate grains. */
const REST_SCALE = 0.88;

const CELL_PERCENT = 100 / GRID;

const GROW_MS = 340;

const APPEAR_MS = 200;

/** A grain fades over the last part of its fall, so none is left showing under the badge. */
const FADE_SHARE = 0.3;

const STILL_FADE = 'opacity 200ms linear';

/** The size of a cell and the curve of a fall are written once on the grid, not on each of its cells. */
const CELLS_STYLE: CellsStyle = {
  '--cell': `${percentOf(1)}%`,
  '--fall-ease': 'cubic-bezier(0.55, 0.085, 0.68, 0.53)',
};

function percentOf(index: number) {
  const percent = index * CELL_PERCENT;
  return Math.round(percent * 1000) / 1000;
}

function placeOf(grain: Grain): React.CSSProperties {
  return {
    left: `${percentOf(grain.col)}%`,
    top: `${percentOf(grain.row)}%`,
  };
}

/** A translate in percent of the cell's own size, so one module is 100%. */
function travelOf(grain: Grain) {
  const across = Math.round(grain.fallX * 100);
  const down = Math.round(grain.fallY * 100);
  return `${across}% ${down}%`;
}

/**
 * A grain falls the way a weight does, slowly at first and then faster, fades out over the end of
 * its fall, and only then shrinks to nothing: the shrinking is what lets it grow back from nothing.
 */
function fallTransitionOf(grain: Grain) {
  const fadeMs = Math.round(grain.fallMs * FADE_SHARE);
  const landsAt = grain.pourDelayMs + grain.fallMs;
  const fall = `translate ${grain.fallMs}ms var(--fall-ease) ${grain.pourDelayMs}ms`;
  const fade = `opacity ${fadeMs}ms linear ${landsAt - fadeMs}ms`;
  const shrink = `scale 1ms linear ${landsAt}ms`;
  return [fall, fade, shrink].join(', ');
}

/** Growing back is in place: the translate is not in the list, so the cell is back on its square at once, unseen. */
function growTransitionOf(grain: Grain) {
  const grow = `scale ${GROW_MS}ms var(--ease-out-strong) ${grain.growDelayMs}ms`;
  const appear = `opacity ${APPEAR_MS}ms linear ${grain.growDelayMs}ms`;
  return [grow, appear].join(', ');
}

function stillOpacityOf(isFallen: boolean) {
  if (isFallen) {
    return 0;
  }
  return 1;
}

function grainStyleOf(
  grain: Grain,
  isFallen: boolean,
  isStill: boolean
): React.CSSProperties {
  const place = placeOf(grain);
  const restScale = String(REST_SCALE);
  if (isStill) {
    return {
      ...place,
      scale: restScale,
      opacity: stillOpacityOf(isFallen),
      transition: STILL_FADE,
    };
  }
  if (isFallen) {
    return {
      ...place,
      translate: travelOf(grain),
      scale: '0',
      opacity: 0,
      transition: fallTransitionOf(grain),
    };
  }
  return {
    ...place,
    translate: '0% 0%',
    scale: restScale,
    opacity: 1,
    transition: growTransitionOf(grain),
  };
}

export type ScanCellsProps = {
  grains: readonly Grain[];
  /** The cells have poured into the badge. */
  isFallen: boolean;
  /** Reduced motion: the cells fade out and in where they stand. */
  isStill: boolean;
};

/**
 * The cells of the code, each one its own element placed on the grid of the code. A change of
 * `isFallen` moves them with transitions of `translate`, `scale` and `opacity` and nothing else, so
 * the browser animates them off the main thread and nothing runs between two changes.
 */
export function ScanCells({ grains, isFallen, isStill }: ScanCellsProps) {
  return (
    <div
      aria-hidden='true'
      style={CELLS_STYLE}
      className='absolute inset-0 forced-colors:*:bg-[CanvasText]'
    >
      {grains.map((grain) => (
        <span
          key={`${grain.col}-${grain.row}`}
          style={grainStyleOf(grain, isFallen, isStill)}
          className='bg-foreground absolute size-(--cell) rounded-[30%]'
        />
      ))}
    </div>
  );
}

import { hashOf } from '@/registry/ndeko/lib/seeded';

export const GRID = 15;

/** An eye is the mark at a corner of a code: a ring of modules round an empty ring and a dot. */
const EYE = 5;

const EYE_MARGIN = 1;

const DATA_DENSITY_PERCENT = 50;

/** The padding of the card round the code and the gap under it, in modules: the grains need them to know how far the badge is. */
export const CARD_PADDING = 1.25;

export const BADGE_GAP = 1.25;

/** A grain ends this far into the badge, where the badge hides it. */
const SINK = 0.9;

const LAND_AT = GRID + CARD_PADDING + BADGE_GAP + SINK;

/** The longest fall, from the top row, in milliseconds. A nearer grain falls for less, as under gravity. */
const FALL_MS = 700;

/** The bottom row sets off first and the top row this long after it. */
const POUR_SPAN_MS = 520;

const POUR_JITTER_MS = 140;

/** The cells grow back from the top left corner to the bottom right one in this span. */
const GROW_SPAN_MS = 600;

const GROW_JITTER_MS = 80;

/** How far to the middle of the code a grain drifts on its way down, so the cells gather into a stream. */
const FUNNEL = 0.6;

export type Grain = {
  col: number;
  row: number;
  /** How far the grain travels across, in modules, to reach the stream. */
  fallX: number;
  /** How far it travels down, in modules, to reach the badge. */
  fallY: number;
  fallMs: number;
  /** When it sets off, counted from the moment the code is scanned. */
  pourDelayMs: number;
  /** When it starts to grow back, counted from the moment the code is ready again. */
  growDelayMs: number;
};

type Spot = {
  col: number;
  row: number;
};

type Offsets = {
  across: number;
  down: number;
};

const EYE_CORNERS: readonly Spot[] = [
  { col: 0, row: 0 },
  { col: GRID - EYE, row: 0 },
  { col: 0, row: GRID - EYE },
];

function hundredthsOf(value: number) {
  return Math.round(value * 100) / 100;
}

function offsetsIn(corner: Spot, spot: Spot): Offsets {
  return { across: spot.col - corner.col, down: spot.row - corner.row };
}

function isInsideBox(offsets: Offsets, from: number, to: number) {
  const isInsideAcross = offsets.across >= from && offsets.across < to;
  const isInsideDown = offsets.down >= from && offsets.down < to;
  return isInsideAcross && isInsideDown;
}

function eyeHolding(spot: Spot, margin: number) {
  return EYE_CORNERS.find((corner) => {
    const offsets = offsetsIn(corner, spot);
    return isInsideBox(offsets, -margin, EYE + margin);
  });
}

function isOnEyeRing(offsets: Offsets) {
  const last = EYE - 1;
  const isEdgeAcross = offsets.across === 0 || offsets.across === last;
  const isEdgeDown = offsets.down === 0 || offsets.down === last;
  return isEdgeAcross || isEdgeDown;
}

function isEyeDot(offsets: Offsets) {
  const middle = (EYE - 1) / 2;
  const isMiddleAcross = offsets.across === middle;
  const isMiddleDown = offsets.down === middle;
  return isMiddleAcross && isMiddleDown;
}

function isDataModule(value: string, spot: Spot) {
  const hash = hashOf(`${value}:${spot.col}:${spot.row}`);
  const share = (hash >>> 11) % 100;
  return share < DATA_DENSITY_PERCENT;
}

function isFilled(value: string, spot: Spot) {
  const eye = eyeHolding(spot, 0);
  if (eye) {
    const offsets = offsetsIn(eye, spot);
    return isOnEyeRing(offsets) || isEyeDot(offsets);
  }
  const isBesideEye = eyeHolding(spot, EYE_MARGIN) !== undefined;
  if (isBesideEye) {
    return false;
  }
  return isDataModule(value, spot);
}

/** A steady number between 0 and 1 for a spot, so a grain never changes its mind between two renders. */
function jitterOf(value: string, spot: Spot) {
  const hash = hashOf(`${value}|${spot.col}|${spot.row}|grain`);
  const thousandths = (hash >>> 6) % 1000;
  return thousandths / 1000;
}

function grainOf(value: string, spot: Spot): Grain {
  const jitter = jitterOf(value, spot);
  const fallY = LAND_AT - spot.row;
  const towardsStream = GRID / 2 - (spot.col + 0.5);
  const nearness = fallY / LAND_AT;
  const fallMs = Math.round(FALL_MS * Math.sqrt(nearness));
  const rowsBelow = (GRID - 1 - spot.row) / (GRID - 1);
  const pourDelayMs = Math.round(
    rowsBelow * POUR_SPAN_MS + jitter * POUR_JITTER_MS
  );
  const diagonal = (spot.col + spot.row) / (2 * (GRID - 1));
  const growDelayMs = Math.round(
    diagonal * GROW_SPAN_MS + jitter * GROW_JITTER_MS
  );
  return {
    col: spot.col,
    row: spot.row,
    fallX: hundredthsOf(towardsStream * FUNNEL),
    fallY: hundredthsOf(fallY),
    fallMs,
    pourDelayMs,
    growDelayMs,
  };
}

/**
 * The cells of a code drawn from a text, each with the way it falls into the badge and the way it
 * grows back. The same text always gives the same code, on the server and in the browser.
 */
export function grainsOf(value: string): Grain[] {
  const grains: Grain[] = [];
  for (let row = 0; row < GRID; row += 1) {
    for (let col = 0; col < GRID; col += 1) {
      const spot: Spot = { col, row };
      if (isFilled(value, spot)) {
        grains.push(grainOf(value, spot));
      }
    }
  }
  return grains;
}

'use client';

import { useState } from 'react';

/** Whether a mouse or a pen rests on an element. A finger does not hover, so a touch never counts. */
export function useHover() {
  const [isHovered, setIsHovered] = useState(false);

  function hoverStarts(event: React.PointerEvent<HTMLElement>) {
    if (event.pointerType !== 'touch') {
      setIsHovered(true);
    }
  }

  function hoverEnds() {
    setIsHovered(false);
  }

  const hoverHandlers = {
    onPointerEnter: hoverStarts,
    onPointerLeave: hoverEnds,
  };

  return { isHovered, hoverHandlers };
}
